  ('home.hero', 'Hero', '{"headline": "Considered objects for everyday life.", "subtext": "Home, kitchen, travel, and more — designed to be used, not just displayed.", "primaryCta": {"label": "Shop New Arrivals", "href": "/collections/new-arrivals"}, "secondaryCta": {"label": "Explore the Edit", "href": "/collections"}, "images": [{"mediaId": null, "url": "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?q=80&w=1800&auto=format&fit=crop", "altText": "Considered living room styling", "width": 1800, "height": 1100}, {"mediaId": null, "url": "https://images.unsplash.com/photo-1592194996308-7b43878e84a6?q=80&w=1800&auto=format&fit=crop", "altText": "Warm, quiet lifestyle interior", "width": 1800, "height": 1100}, {"mediaId": null, "url": "https://images.unsplash.com/photo-1524758631624-e2822e304c36?q=80&w=1800&auto=format&fit=crop", "altText": "Sunlit interior with greenery", "width": 1800, "height": 1100}]}'::jsonb, '{"headline": "Considered objects for everyday life.", "subtext": "Home, kitchen, travel, and more — designed to be used, not just displayed.", "primaryCta": {"label": "Shop New Arrivals", "href": "/collections/new-arrivals"}, "secondaryCta": {"label": "Explore the Edit", "href": "/collections"}, "images": [{"mediaId": null, "url": "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?q=80&w=1800&auto=format&fit=crop", "altText": "Considered living room styling", "width": 1800, "height": 1100}, {"mediaId": null, "url": "https://images.unsplash.com/photo-1592194996308-7b43878e84a6?q=80&w=1800&auto=format&fit=crop", "altText": "Warm, quiet lifestyle interior", "width": 1800, "height": 1100}, {"mediaId": null, "url": "https://images.unsplash.com/photo-1524758631624-e2822e304c36?q=80&w=1800&auto=format&fit=crop", "altText": "Sunlit interior with greenery", "width": 1800, "height": 1100}]}'::jsonb),
  ('home.announcement', 'Announcement Bar', '{"messages": ["Free shipping across India on every order", "Get an extra 10% off on prepaid orders", "7-day hassle-free returns on every order", "Discover more everyday — loved by 50,000+ customers"]}'::jsonb, '{"messages": ["Free shipping across India on every order", "Get an extra 10% off on prepaid orders", "7-day hassle-free returns on every order", "Discover more everyday — loved by 50,000+ customers"]}'::jsonb),
