  ('home.value_props', 'Value Props', '{"eyebrow": "Why ZEEVARA", "title": "Why Choose Us", "items": [{"icon": "gem", "title": "Considered Materials", "description": "Stoneware, wood, and textiles chosen for how they age, not just how they photograph."}, {"icon": "rotate-ccw", "title": "7-Day Returns, No Questions", "description": "Free returns within 7 days on unused items — simple, no fine print."}, {"icon": "leaf", "title": "Carbon-Neutral Shipping", "description": "Every order ships carbon-neutral across India, at no extra cost to you."}, {"icon": "ruler", "title": "Design-Led, Not Trend-Led", "description": "We ship fewer, better things — built to still look right a year from now."}]}'::jsonb, '{"eyebrow": "Why ZEEVARA", "title": "Why Choose Us", "items": [{"icon": "gem", "title": "Considered Materials", "description": "Stoneware, wood, and textiles chosen for how they age, not just how they photograph."}, {"icon": "rotate-ccw", "title": "7-Day Returns, No Questions", "description": "Free returns within 7 days on unused items — simple, no fine print."}, {"icon": "leaf", "title": "Carbon-Neutral Shipping", "description": "Every order ships carbon-neutral across India, at no extra cost to you."}, {"icon": "ruler", "title": "Design-Led, Not Trend-Led", "description": "We ship fewer, better things — built to still look right a year from now."}]}'::jsonb),
  ('home.testimonials', 'Testimonials', '{"title": "What our customers say about us", "items": [{"id": "t1", "author": "Ananya", "location": "Bengaluru", "rating": 5, "quote": "Every order feels considered, right down to the packaging. My home has slowly filled with ZEEVARA pieces over the past year and nothing has disappointed."}, {"id": "t2", "author": "Kabir", "location": "Mumbai", "rating": 5, "quote": "I was skeptical about buying home goods online without touching them first, but the quality has matched the photos every single time."}, {"id": "t3", "author": "Meera", "location": "Kochi", "rating": 4, "quote": "Delivery bhi time pe aa gayi aur return process bhi bahut smooth tha — size exchange karne mein koi dikkat nahi hui."}, {"id": "t4", "author": "Rohan", "location": "Delhi", "rating": 5, "quote": "The kind of brand where you stop comparing prices elsewhere because you already know the quality holds up."}, {"id": "t5", "author": "Diya", "location": "Pune", "rating": 5, "quote": "Ek friend ke ghar pe dekha tha, ab main bhi order karti rehti hoon. Quality bilkul photos jaisi hi hai, paisa vasool."}, {"id": "t6", "author": "Aditya", "location": "Hyderabad", "rating": 4, "quote": "Considered design without the markup you''d expect from ''considered design'' — that balance is rare."}]}'::jsonb, '{"title": "What our customers say about us", "items": [{"id": "t1", "author": "Ananya", "location": "Bengaluru", "rating": 5, "quote": "Every order feels considered, right down to the packaging. My home has slowly filled with ZEEVARA pieces over the past year and nothing has disappointed."}, {"id": "t2", "author": "Kabir", "location": "Mumbai", "rating": 5, "quote": "I was skeptical about buying home goods online without touching them first, but the quality has matched the photos every single time."}, {"id": "t3", "author": "Meera", "location": "Kochi", "rating": 4, "quote": "Delivery bhi time pe aa gayi aur return process bhi bahut smooth tha — size exchange karne mein koi dikkat nahi hui."}, {"id": "t4", "author": "Rohan", "location": "Delhi", "rating": 5, "quote": "The kind of brand where you stop comparing prices elsewhere because you already know the quality holds up."}, {"id": "t5", "author": "Diya", "location": "Pune", "rating": 5, "quote": "Ek friend ke ghar pe dekha tha, ab main bhi order karti rehti hoon. Quality bilkul photos jaisi hi hai, paisa vasool."}, {"id": "t6", "author": "Aditya", "location": "Hyderabad", "rating": 4, "quote": "Considered design without the markup you''d expect from ''considered design'' — that balance is rare."}]}'::jsonb),
  ('home.lifestyle_banner', 'Lifestyle Banner', '{"quote": "\"Discover more everyday\" isn''t a tagline — it''s how we choose what to make.", "image": {"mediaId": null, "url": "https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?q=80&w=2200&auto=format&fit=crop", "altText": "Full-bleed editorial interior shot", "width": 2200, "height": 1400}}'::jsonb, '{"quote": "\"Discover more everyday\" isn''t a tagline — it''s how we choose what to make.", "image": {"mediaId": null, "url": "https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?q=80&w=2200&auto=format&fit=crop", "altText": "Full-bleed editorial interior shot", "width": 2200, "height": 1400}}'::jsonb),
  ('home.featured_collection', 'Featured Collection', '{"eyebrow": "Featured Collection", "ctaLabel": "Shop the Edit", "image": {"mediaId": null, "url": "https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?q=80&w=1600&auto=format&fit=crop", "altText": "The Work-From-Anywhere Edit, editorial banner", "width": 1600, "height": 2000}}'::jsonb, '{"eyebrow": "Featured Collection", "ctaLabel": "Shop the Edit", "image": {"mediaId": null, "url": "https://images.unsplash.com/photo-1493663284031-b7e3aefcae8e?q=80&w=1600&auto=format&fit=crop", "altText": "The Work-From-Anywhere Edit, editorial banner", "width": 1600, "height": 2000}}'::jsonb),
