  ('home.category_tabs', 'Category Tabs', '{"eyebrow": "Browse", "title": "Shop by Category", "featured": [{"handle": "home-decor", "description": "Considered objects for rooms that feel like you."}, {"handle": "kitchen", "description": "Tools designed to be seen, not hidden away."}, {"handle": "office", "description": "A calmer way to get things done."}, {"handle": "travel", "description": "Considered companions for wherever you''re headed."}, {"handle": "fitness", "description": "Equipment built for a routine that sticks."}, {"handle": "beauty", "description": "Quiet luxury for a daily routine."}]}'::jsonb, '{"eyebrow": "Browse", "title": "Shop by Category", "featured": [{"handle": "home-decor", "description": "Considered objects for rooms that feel like you."}, {"handle": "kitchen", "description": "Tools designed to be seen, not hidden away."}, {"handle": "office", "description": "A calmer way to get things done."}, {"handle": "travel", "description": "Considered companions for wherever you''re headed."}, {"handle": "fitness", "description": "Equipment built for a routine that sticks."}, {"handle": "beauty", "description": "Quiet luxury for a daily routine."}]}'::jsonb),
  ('faq', 'FAQ', '{"eyebrow": "Support", "title": "Frequently Asked Questions", "description": "Can''t find what you''re looking for? Reach out at support@zeevara.in.", "categories": [{"id": "faq-orders-shipping", "heading": "Orders & Shipping", "items": [{"id": "faq-q1", "question": "How long does delivery take?", "answer": "Most orders are processed within 1-2 business days and delivered within 2-5 business days, depending on your location. Metro cities typically see faster delivery, while remote areas may take a day or two longer."}, {"id": "faq-q2", "question": "Do you offer free shipping?", "answer": "Yes — every order ships free across India, with no minimum order value."}, {"id": "faq-q3", "question": "Can I track my order?", "answer": "Once your order ships, you''ll receive a tracking link by email and SMS. You can also check order status by contacting our support team with your order number."}, {"id": "faq-q4", "question": "Is Cash on Delivery available?", "answer": "Cash on Delivery is available on most pincodes for orders under ₹5,000. Prepaid orders are processed and dispatched faster, and occasionally carry a small additional discount."}, {"id": "faq-q5", "question": "Do you ship internationally?", "answer": "Not yet — we currently ship only within India. We''re evaluating international shipping and will announce it here when it becomes available."}]}, {"id": "faq-returns-exchanges", "heading": "Returns & Exchanges", "items": [{"id": "faq-q6", "question": "What is your return policy?", "answer": "We accept returns within 7 days of delivery on unused items in their original packaging. See our full Return Policy page for the complete process and exceptions."}, {"id": "faq-q7", "question": "How do I start a return?", "answer": "Contact support@zeevara.in with your order number and reason for return. We''ll send a prepaid return label for eligible items and process your refund once the item passes inspection."}, {"id": "faq-q8", "question": "How long do refunds take?", "answer": "Refunds are issued within 5-7 business days of us receiving and inspecting the returned item, back to your original payment method."}, {"id": "faq-q9", "question": "Can I exchange an item for a different size or color?", "answer": "Yes, subject to availability. Request an exchange the same way you''d request a return, and let us know the size or color you''d like instead."}]}, {"id": "faq-product-care", "heading": "Product Care", "items": [{"id": "faq-q10", "question": "How should I care for ceramic and stoneware pieces?", "answer": "Most of our ceramic pieces are dishwasher and microwave safe unless noted otherwise on the product page. Avoid abrasive scouring pads, which can dull the glaze over time."}, {"id": "faq-q11", "question": "Are your textiles machine washable?", "answer": "Check each product''s care instructions — most linen and cotton pieces are machine washable on a cold, gentle cycle, while wool and specialty textiles are spot-clean or dry-clean only."}, {"id": "faq-q12", "question": "How do I care for wood and metal home pieces?", "answer": "Wipe wood pieces with a dry or slightly damp cloth and avoid prolonged direct sunlight. Brass and metal hardware can be polished occasionally with a soft cloth to maintain its finish."}]}, {"id": "faq-payments-pricing", "heading": "Payments & Pricing", "items": [{"id": "faq-q13", "question": "What payment methods do you accept?", "answer": "We accept all major credit and debit cards, UPI, net banking, and Cash on Delivery on eligible orders."}, {"id": "faq-q14", "question": "Is it safe to pay online on ZEEVARA?", "answer": "Yes — all payments are processed through secure, encrypted checkout. We never store your full card details on our servers."}, {"id": "faq-q15", "question": "Do prices include taxes?", "answer": "Yes, all prices shown are inclusive of applicable taxes. The price you see at checkout is the price you pay, with no hidden fees."}]}]}'::jsonb, '{"eyebrow": "Support", "title": "Frequently Asked Questions", "description": "Can''t find what you''re looking for? Reach out at support@zeevara.in.", "categories": [{"id": "faq-orders-shipping", "heading": "Orders & Shipping", "items": [{"id": "faq-q1", "question": "How long does delivery take?", "answer": "Most orders are processed within 1-2 business days and delivered within 2-5 business days, depending on your location. Metro cities typically see faster delivery, while remote areas may take a day or two longer."}, {"id": "faq-q2", "question": "Do you offer free shipping?", "answer": "Yes — every order ships free across India, with no minimum order value."}, {"id": "faq-q3", "question": "Can I track my order?", "answer": "Once your order ships, you''ll receive a tracking link by email and SMS. You can also check order status by contacting our support team with your order number."}, {"id": "faq-q4", "question": "Is Cash on Delivery available?", "answer": "Cash on Delivery is available on most pincodes for orders under ₹5,000. Prepaid orders are processed and dispatched faster, and occasionally carry a small additional discount."}, {"id": "faq-q5", "question": "Do you ship internationally?", "answer": "Not yet — we currently ship only within India. We''re evaluating international shipping and will announce it here when it becomes available."}]}, {"id": "faq-returns-exchanges", "heading": "Returns & Exchanges", "items": [{"id": "faq-q6", "question": "What is your return policy?", "answer": "We accept returns within 7 days of delivery on unused items in their original packaging. See our full Return Policy page for the complete process and exceptions."}, {"id": "faq-q7", "question": "How do I start a return?", "answer": "Contact support@zeevara.in with your order number and reason for return. We''ll send a prepaid return label for eligible items and process your refund once the item passes inspection."}, {"id": "faq-q8", "question": "How long do refunds take?", "answer": "Refunds are issued within 5-7 business days of us receiving and inspecting the returned item, back to your original payment method."}, {"id": "faq-q9", "question": "Can I exchange an item for a different size or color?", "answer": "Yes, subject to availability. Request an exchange the same way you''d request a return, and let us know the size or color you''d like instead."}]}, {"id": "faq-product-care", "heading": "Product Care", "items": [{"id": "faq-q10", "question": "How should I care for ceramic and stoneware pieces?", "answer": "Most of our ceramic pieces are dishwasher and microwave safe unless noted otherwise on the product page. Avoid abrasive scouring pads, which can dull the glaze over time."}, {"id": "faq-q11", "question": "Are your textiles machine washable?", "answer": "Check each product''s care instructions — most linen and cotton pieces are machine washable on a cold, gentle cycle, while wool and specialty textiles are spot-clean or dry-clean only."}, {"id": "faq-q12", "question": "How do I care for wood and metal home pieces?", "answer": "Wipe wood pieces with a dry or slightly damp cloth and avoid prolonged direct sunlight. Brass and metal hardware can be polished occasionally with a soft cloth to maintain its finish."}]}, {"id": "faq-payments-pricing", "heading": "Payments & Pricing", "items": [{"id": "faq-q13", "question": "What payment methods do you accept?", "answer": "We accept all major credit and debit cards, UPI, net banking, and Cash on Delivery on eligible orders."}, {"id": "faq-q14", "question": "Is it safe to pay online on ZEEVARA?", "answer": "Yes — all payments are processed through secure, encrypted checkout. We never store your full card details on our servers."}, {"id": "faq-q15", "question": "Do prices include taxes?", "answer": "Yes, all prices shown are inclusive of applicable taxes. The price you see at checkout is the price you pay, with no hidden fees."}]}]}'::jsonb),
  ('contact.intro', 'Contact Page', '{"eyebrow": "Get in touch", "title": "Contact Us", "description": "Questions about an order, a product, or anything else — we''re here to help.", "contactEmail": "support@zeevara.in", "contactHours": "Mon–Sat, 10am–6pm IST", "faqPrompt": {"label": "Check our FAQ", "href": "/faq"}}'::jsonb, '{"eyebrow": "Get in touch", "title": "Contact Us", "description": "Questions about an order, a product, or anything else — we''re here to help.", "contactEmail": "support@zeevara.in", "contactHours": "Mon–Sat, 10am–6pm IST", "faqPrompt": {"label": "Check our FAQ", "href": "/faq"}}'::jsonb)
