insert into public.pages (slug, title, draft_body_json, draft_body_html, draft_meta, published_body_json, published_body_html, published_meta, is_system, sort_order) values
  ('about', 'Considered objects for everyday life.', '{"type": "doc", "content": []}'::jsonb, '<p>ZEEVARA started with a simple frustration: most home goods online were either disposable and cheap, or beautiful and absurdly overpriced. We wanted a third option — pieces considered enough to keep for years, priced honestly enough to actually use every day.</p><p>Today that''s grown into a catalog spanning home decor, kitchen, office, travel, fitness, and more — but the standard hasn''t changed. Every product we add has to earn its place: it has to be genuinely useful, built to last, and worth the price on the tag. Discover more everyday.</p>', '{"eyebrow": "Our story", "heroImage": {"mediaId": null, "url": "https://images.unsplash.com/photo-1524758631624-e2822e304c36?q=80&w=1800&auto=format&fit=crop", "altText": "ZEEVARA studio, considered objects for everyday life", "width": 1800, "height": 1200}, "principles": [{"title": "Considered Materials", "body": "We choose materials for how they age, not just how they photograph — stoneware that develops character, wood that softens with use, textiles that get better after every wash."}, {"title": "Design-Led, Not Trend-Led", "body": "We''d rather ship fewer, better things than chase every micro-trend. Most of what we sell today looked the same a year ago, and will look the same a year from now."}, {"title": "Priced Honestly", "body": "No inflated ''original'' prices marked down to look generous. What you see is what it costs, with margin only where it''s earned."}], "stats": [{"value": 6, "suffix": "", "label": "Years designing everyday objects"}, {"value": 50000, "suffix": "+", "label": "Customers across India"}, {"value": 12, "suffix": "", "label": "Product categories"}, {"value": 4.6, "suffix": "/5", "label": "Average customer rating", "decimals": 1}], "closing": {"heading": "Discover the collection.", "ctaLabel": "Shop All", "ctaHref": "/collections"}}'::jsonb, '{"type": "doc", "content": []}'::jsonb, '<p>ZEEVARA started with a simple frustration: most home goods online were either disposable and cheap, or beautiful and absurdly overpriced. We wanted a third option — pieces considered enough to keep for years, priced honestly enough to actually use every day.</p><p>Today that''s grown into a catalog spanning home decor, kitchen, office, travel, fitness, and more — but the standard hasn''t changed. Every product we add has to earn its place: it has to be genuinely useful, built to last, and worth the price on the tag. Discover more everyday.</p>', '{"eyebrow": "Our story", "heroImage": {"mediaId": null, "url": "https://images.unsplash.com/photo-1524758631624-e2822e304c36?q=80&w=1800&auto=format&fit=crop", "altText": "ZEEVARA studio, considered objects for everyday life", "width": 1800, "height": 1200}, "principles": [{"title": "Considered Materials", "body": "We choose materials for how they age, not just how they photograph — stoneware that develops character, wood that softens with use, textiles that get better after every wash."}, {"title": "Design-Led, Not Trend-Led", "body": "We''d rather ship fewer, better things than chase every micro-trend. Most of what we sell today looked the same a year ago, and will look the same a year from now."}, {"title": "Priced Honestly", "body": "No inflated ''original'' prices marked down to look generous. What you see is what it costs, with margin only where it''s earned."}], "stats": [{"value": 6, "suffix": "", "label": "Years designing everyday objects"}, {"value": 50000, "suffix": "+", "label": "Customers across India"}, {"value": 12, "suffix": "", "label": "Product categories"}, {"value": 4.6, "suffix": "/5", "label": "Average customer rating", "decimals": 1}], "closing": {"heading": "Discover the collection.", "ctaLabel": "Shop All", "ctaHref": "/collections"}}'::jsonb, true, 0),
  ('privacy', 'Privacy Policy', '{"type": "doc", "content": []}'::jsonb, '<h2>Information We Collect</h2><p>When you browse ZEEVARA or place an order, we collect information you provide directly (name, email, shipping address, phone number, payment details) and information collected automatically (device type, browser, pages viewed, and approximate location via IP address) to operate and improve the site.</p><h2>How We Use Your Information</h2><ul><li>To process and deliver your orders, and communicate about their status</li><li>To respond to customer support requests</li><li>To send order-related and, if you''ve opted in, marketing emails</li><li>To improve our product catalog, site performance, and shopping experience</li><li>To detect and prevent fraud</li></ul><h2>Cookies</h2><p>We use cookies and similar technologies to keep you signed in, remember your cart and wishlist, and understand how the site is used. You can disable cookies in your browser settings, though some features may not work correctly as a result.</p><h2>Third-Party Processors</h2><p>When our commerce platform is connected, order and payment information will be shared with the payment processor and shipping/logistics partners solely to fulfil your order. We do not sell your personal information to third parties.</p><h2>Your Rights</h2><p>You can request a copy of the personal data we hold about you, ask us to correct inaccurate information, or request deletion of your account and associated data, subject to legal record-keeping requirements. Contact support@zeevara.in to make a request.</p><h2>Data Retention &amp; Security</h2><p>We retain order data for as long as needed to comply with tax and accounting obligations, and use industry-standard safeguards to protect it against unauthorized access.</p><h2>Governing Law</h2><p>This policy is governed by the laws of India. For any privacy-related questions or concerns, reach out to support@zeevara.in.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, '{"type": "doc", "content": []}'::jsonb, '<h2>Information We Collect</h2><p>When you browse ZEEVARA or place an order, we collect information you provide directly (name, email, shipping address, phone number, payment details) and information collected automatically (device type, browser, pages viewed, and approximate location via IP address) to operate and improve the site.</p><h2>How We Use Your Information</h2><ul><li>To process and deliver your orders, and communicate about their status</li><li>To respond to customer support requests</li><li>To send order-related and, if you''ve opted in, marketing emails</li><li>To improve our product catalog, site performance, and shopping experience</li><li>To detect and prevent fraud</li></ul><h2>Cookies</h2><p>We use cookies and similar technologies to keep you signed in, remember your cart and wishlist, and understand how the site is used. You can disable cookies in your browser settings, though some features may not work correctly as a result.</p><h2>Third-Party Processors</h2><p>When our commerce platform is connected, order and payment information will be shared with the payment processor and shipping/logistics partners solely to fulfil your order. We do not sell your personal information to third parties.</p><h2>Your Rights</h2><p>You can request a copy of the personal data we hold about you, ask us to correct inaccurate information, or request deletion of your account and associated data, subject to legal record-keeping requirements. Contact support@zeevara.in to make a request.</p><h2>Data Retention &amp; Security</h2><p>We retain order data for as long as needed to comply with tax and accounting obligations, and use industry-standard safeguards to protect it against unauthorized access.</p><h2>Governing Law</h2><p>This policy is governed by the laws of India. For any privacy-related questions or concerns, reach out to support@zeevara.in.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, true, 1),
  ('terms', 'Terms of Service', '{"type": "doc", "content": []}'::jsonb, '<h2>Acceptance of Terms</h2><p>By accessing or using ZEEVARA, you agree to be bound by these Terms of Service. If you don''t agree with any part of these terms, please don''t use the site.</p><h2>Orders &amp; Pricing</h2><p>All prices are listed in Indian Rupees (₹) and are inclusive of applicable taxes unless stated otherwise. We reserve the right to correct pricing errors and to limit order quantities. An order is confirmed only once you receive an order confirmation email.</p><h2>Product Descriptions</h2><p>We aim to describe and photograph every product as accurately as possible. Minor variations in color or finish (particularly for handmade ceramic and wood pieces) are natural and not considered defects.</p><h2>Account Responsibilities</h2><p>If you create an account, you''re responsible for maintaining the confidentiality of your login details and for all activity under your account. Notify us immediately of any unauthorized use.</p><h2>Intellectual Property</h2><p>All content on this site — including product photography, copy, and the ZEEVARA name and logo — is the property of ZEEVARA and may not be reproduced without permission.</p><h2>Limitation of Liability</h2><p>ZEEVARA is not liable for indirect or incidental damages arising from the use of our products or site, to the fullest extent permitted by law.</p><h2>Changes to These Terms</h2><p>We may update these terms from time to time. Continued use of the site after changes are posted constitutes acceptance of the updated terms.</p><h2>Governing Law</h2><p>These terms are governed by the laws of India. Questions about these terms can be sent to support@zeevara.in.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, '{"type": "doc", "content": []}'::jsonb, '<h2>Acceptance of Terms</h2><p>By accessing or using ZEEVARA, you agree to be bound by these Terms of Service. If you don''t agree with any part of these terms, please don''t use the site.</p><h2>Orders &amp; Pricing</h2><p>All prices are listed in Indian Rupees (₹) and are inclusive of applicable taxes unless stated otherwise. We reserve the right to correct pricing errors and to limit order quantities. An order is confirmed only once you receive an order confirmation email.</p><h2>Product Descriptions</h2><p>We aim to describe and photograph every product as accurately as possible. Minor variations in color or finish (particularly for handmade ceramic and wood pieces) are natural and not considered defects.</p><h2>Account Responsibilities</h2><p>If you create an account, you''re responsible for maintaining the confidentiality of your login details and for all activity under your account. Notify us immediately of any unauthorized use.</p><h2>Intellectual Property</h2><p>All content on this site — including product photography, copy, and the ZEEVARA name and logo — is the property of ZEEVARA and may not be reproduced without permission.</p><h2>Limitation of Liability</h2><p>ZEEVARA is not liable for indirect or incidental damages arising from the use of our products or site, to the fullest extent permitted by law.</p><h2>Changes to These Terms</h2><p>We may update these terms from time to time. Continued use of the site after changes are posted constitutes acceptance of the updated terms.</p><h2>Governing Law</h2><p>These terms are governed by the laws of India. Questions about these terms can be sent to support@zeevara.in.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, true, 2),
  ('shipping-policy', 'Shipping Policy', '{"type": "doc", "content": []}'::jsonb, '<h2>Processing Time</h2><p>Orders are processed within 1-2 business days of being placed. During high-demand periods (like sale events), processing may take up to 3 business days. You''ll receive a shipping confirmation email as soon as your order leaves our warehouse.</p><h2>Delivery Estimates by Region</h2><p>Once shipped, delivery typically takes:</p><ul><li>Metro cities (Mumbai, Delhi NCR, Bengaluru, Chennai, Hyderabad, Kolkata, Pune): 2-4 business days</li><li>Other cities and towns: 4-6 business days</li><li>Remote and rural pincodes: 6-8 business days</li></ul><h2>Shipping Costs</h2><p>Every order ships free across India, with no minimum order value.</p><h2>Order Tracking</h2><p>You''ll receive a tracking link by email and SMS as soon as your order ships. If you haven''t received tracking within 3 business days of ordering, contact us at support@zeevara.in with your order number.</p><h2>International Shipping</h2><p>We currently ship only within India. We know international shipping is frequently requested, and we''re actively evaluating it — this page will be updated when it becomes available.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, '{"type": "doc", "content": []}'::jsonb, '<h2>Processing Time</h2><p>Orders are processed within 1-2 business days of being placed. During high-demand periods (like sale events), processing may take up to 3 business days. You''ll receive a shipping confirmation email as soon as your order leaves our warehouse.</p><h2>Delivery Estimates by Region</h2><p>Once shipped, delivery typically takes:</p><ul><li>Metro cities (Mumbai, Delhi NCR, Bengaluru, Chennai, Hyderabad, Kolkata, Pune): 2-4 business days</li><li>Other cities and towns: 4-6 business days</li><li>Remote and rural pincodes: 6-8 business days</li></ul><h2>Shipping Costs</h2><p>Every order ships free across India, with no minimum order value.</p><h2>Order Tracking</h2><p>You''ll receive a tracking link by email and SMS as soon as your order ships. If you haven''t received tracking within 3 business days of ordering, contact us at support@zeevara.in with your order number.</p><h2>International Shipping</h2><p>We currently ship only within India. We know international shipping is frequently requested, and we''re actively evaluating it — this page will be updated when it becomes available.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, true, 3),
  ('return-policy', 'Return Policy', '{"type": "doc", "content": []}'::jsonb, '<h2>Our Promise</h2><p>If something you ordered doesn''t work out, we want to make it right. We accept returns on eligible items within 7 days of delivery, no complicated reasons required.</p><h2>Eligibility Window</h2><p>Returns are accepted within 7 days of the delivery date shown on your tracking confirmation. Items must be unused, in their original packaging, and in resellable condition. Products showing signs of use, damage not caused by shipping, or missing original packaging may not be eligible for a full refund.</p><h2>How to Start a Return</h2><ol><li>Email support@zeevara.in with your order number and the item(s) you''d like to return, along with a brief reason.</li><li>Our support team will confirm eligibility and send a prepaid return shipping label within 1-2 business days.</li><li>Pack the item securely in its original packaging where possible and hand it to the courier using the provided label.</li></ol><h2>Refund Timelines</h2><p>Once we receive and inspect your return, refunds are processed within 5-7 business days to your original payment method. For Cash on Delivery orders, refunds are issued via bank transfer or store credit, whichever you prefer. You''ll receive an email confirmation once your refund has been issued.</p><h2>Exchanges</h2><p>Need a different size or color instead of a refund? Let us know when you request your return and we''ll ship the replacement as soon as the original item is on its way back to us, subject to stock availability.</p><h2>Non-Returnable Items</h2><p>For hygiene reasons, opened beauty and personal care items cannot be returned unless defective. Final-sale items (marked as such on the product page) and personalized or made-to-order pieces are also not eligible for return.</p><h2>Damaged or Incorrect Items</h2><p>If your order arrives damaged or you received the wrong item, contact us within 48 hours of delivery with photos of the item and packaging. We''ll arrange a free replacement or full refund — no return shipping cost to you.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, '{"type": "doc", "content": []}'::jsonb, '<h2>Our Promise</h2><p>If something you ordered doesn''t work out, we want to make it right. We accept returns on eligible items within 7 days of delivery, no complicated reasons required.</p><h2>Eligibility Window</h2><p>Returns are accepted within 7 days of the delivery date shown on your tracking confirmation. Items must be unused, in their original packaging, and in resellable condition. Products showing signs of use, damage not caused by shipping, or missing original packaging may not be eligible for a full refund.</p><h2>How to Start a Return</h2><ol><li>Email support@zeevara.in with your order number and the item(s) you''d like to return, along with a brief reason.</li><li>Our support team will confirm eligibility and send a prepaid return shipping label within 1-2 business days.</li><li>Pack the item securely in its original packaging where possible and hand it to the courier using the provided label.</li></ol><h2>Refund Timelines</h2><p>Once we receive and inspect your return, refunds are processed within 5-7 business days to your original payment method. For Cash on Delivery orders, refunds are issued via bank transfer or store credit, whichever you prefer. You''ll receive an email confirmation once your refund has been issued.</p><h2>Exchanges</h2><p>Need a different size or color instead of a refund? Let us know when you request your return and we''ll ship the replacement as soon as the original item is on its way back to us, subject to stock availability.</p><h2>Non-Returnable Items</h2><p>For hygiene reasons, opened beauty and personal care items cannot be returned unless defective. Final-sale items (marked as such on the product page) and personalized or made-to-order pieces are also not eligible for return.</p><h2>Damaged or Incorrect Items</h2><p>If your order arrives damaged or you received the wrong item, contact us within 48 hours of delivery with photos of the item and packaging. We''ll arrange a free replacement or full refund — no return shipping cost to you.</p>', '{"lastUpdatedLabel": "Last updated: July 2026"}'::jsonb, true, 4)
